import json
from pathlib import Path

data=json.loads(Path('benchmark/source_data.json').read_text())['ml_architecture']
nodes={n['id']:n for n in data['nodes']}
edges=data['edges']

# map criticality -> node width and font size for Mermaid
# width: 140..260 roughly
# font: 12..18
minc=min(n['criticality'] for n in nodes.values())
maxc=max(n['criticality'] for n in nodes.values())

def scale(val, a,b, c,d):
    if b==a: return (c+d)/2
    return c+(val-a)*(d-c)/(b-a)

node_style={}
for nid,n in nodes.items():
    crit=n['criticality']
    w=round(scale(crit,minc,maxc,155,260))
    fs=round(scale(crit,minc,maxc,12,18))
    node_style[nid]=(w,fs)

# throughput -> stroke-width
mint=min(e['throughput_gbps'] for e in edges)
maxt=max(e['throughput_gbps'] for e in edges)

def sw(t):
    return round(scale(t,mint,maxt,1.2,6.5),2)

for e in edges:
    e['stroke']=sw(e['throughput_gbps'])

print('node styles (w,fs):')
for k,v in node_style.items():
    print(k,v)
print('edge stroke sample:',[(e['source'],e['target'],e['throughput_gbps'],e['stroke'],e['flow_type']) for e in edges[:5]])
PY"}
